// Preconditions: pattern must be a compiled regex produced by re_compile and must
// retain a live character-class buffer. We enforce this via attributes.
int compiled = FUZZ_GET_ATTR_INT(pattern, "compiled");
void *charbuf_obj = FUZZ_GET_ATTR_PTR(pattern, "charbuf");
if (!compiled || !charbuf_obj) { FUZZ_BAIL(); }
// Prepare a non-null, non-NUL-terminated text buffer of known length.
std::string text = FUZZ_PARAM_STR();
const char *text_ptr = text.data();
size_t text_len = text.size();
// Choose a max_match_length in [0, text_len + 16] to explore bound behaviors.
unsigned int r = *FUZZ_PARAM(unsigned int);
size_t max_match_length = (size_t)(r % (text_len + 17));
// Output parameter for match length; must be writable and non-null.
size_t out_match_len = 0;
// Invoke the target function.
int rv = re_matchp((re_t)pattern, text_ptr, text_len, max_match_length, &out_match_len);
// Basic safety/property assertions: implementation should never claim a match longer
// than the haystack. If it does, treat as property violation.
FUZZ_ASSERT(out_match_len <= text_len, "match length exceeds text length");
// Keep pattern alive by returning it as an output (no deallocation here).
// Validation: Ensures compiled pattern and char buffer linkage via attributes; exercises
// varying max_match_length and verifies match length sanity.

// Outputs must be defined and non-null on success; initialize to null until we succeed.
regex_t *pattern = nullptr;
void *regex_char_buffer = nullptr;

// Generate a raw pattern buffer (not necessarily null-terminated) and its length.
std::string pat = FUZZ_PARAM_STR();
const char *pat_ptr = pat.data();
size_t pat_len = pat.size();

// Size caller-provided storage for compiled regex nodes and char-class buffer.
// Keep within fuzzer perf limits (<2048 bytes total across allocations).
// Nodes capacity loosely tied to pattern length.
size_t node_cap = pat_len + 8; if (node_cap < 8) node_cap = 8; if (node_cap > 256) node_cap = 256;
// Char-class buffer capacity allows growth for classes and escapes.
size_t cclass_cap = pat_len * 2 + 16; if (cclass_cap < 32) cclass_cap = 32; if (cclass_cap > 1536) cclass_cap = 1536;

// Allocate caller-owned buffers used by the API.
regex_t *nodes = new regex_t[node_cap];
unsigned char *cclass = new unsigned char[cclass_cap];

// Attempt compilation into the provided storage.
int rc = re_compile(pat_ptr, pat_len, (re_t)nodes, cclass);
if (rc != 0) {
    // On failure, do not expose invalid outputs; clean up and bail.
    delete[] nodes;
    delete[] cclass;
    FUZZ_BAIL();
}

// Success: transfer ownership of allocations to fuzzer runtime via outputs.
pattern = nodes;
regex_char_buffer = (void*)cclass;

// Tag attributes to enforce lifetime/linkage in downstream stubs (e.g., re_matchp).
FUZZ_SET_ATTR_INT(pattern, "compiled", 1);
FUZZ_SET_ATTR_PTR(pattern, "charbuf", regex_char_buffer);
FUZZ_SET_ATTR_INT(pattern, "node_capacity", (int)node_cap);
FUZZ_SET_ATTR_INT(regex_char_buffer, "is_charbuf", 1);
FUZZ_SET_ATTR_INT(regex_char_buffer, "charbuf_capacity", (int)cclass_cap);

// Validation: Outputs are non-null only on success; attributes link pattern->charbuf and
// record capacities for later checks.

