import random
import struct
import itertools

# This generator produces valid, interesting inputs for the target fuzzers which
# request arbitrary byte strings for both regex patterns (re_compile) and text
# haystacks (re_matchp). It focuses on generating regex patterns the library is
# likely to accept, including character classes, quantifiers, anchors, groups,
# alternation, escapes, and mixed ASCII/binary. The output is a single bytes
# buffer; the fuzzer harness will slice it as needed for FUZZ_PARAM_STR calls.

# We assume an engine similar to many tiny-regex implementations supporting:
# - Literals
# - .  (any)
# - ^ and $ anchors
# - * + ? quantifiers (greedy)
# - Character classes: [abc], ranges [a-z], negation [^...]
# - Escapes for special chars
# - Grouping (...) and alternation |
# - Possibly repetition of classes and groups
# We avoid malformed constructs to maximize successful compilations.

MAX_OUTPUT = 4096

LITERALS = [
    b"a", b"b", b"c", b"x", b"y", b"z", b"0", b"1", b"9",
    b" ", b"\t", b"\n", b"_", b"-", b"/", b"\\", b".", b"*", b"+", b"?",
]

ANCHORS = [b"^", b"$"]
QUANTIFIERS = [b"*", b"+", b"?"]
SPECIALS = [b"."]

# Some binary chunks to mix into patterns/text safely (escaped where needed in patterns)
BINARY_BYTES = [
    bytes([0x00]), bytes([0x01]), bytes([0x7F]), bytes([0x80]), bytes([0xFF]),
]

SAFE_CLASS_ATOMS = [
    b"a", b"z", b"A", b"Z", b"0", b"9", b"_", b"-", b" ", b"\t",
]

ESCAPABLES = [b"[", b"]", b"(", b")", b"|", b".", b"*", b"+", b"?", b"^", b"$", b"\\"]


def _rand(rng, seq):
    return seq[rng.randrange(len(seq))]


def escape_byte_for_pattern(b: bytes) -> bytes:
    # Escape bytes that would otherwise break the pattern syntax
    if b in ESCAPABLES:
        return b"\\" + b
    # Non-printables, keep as \xNN style for robustness; but many tiny engines
    # may not support \xNN. To stay valid, we embed them inside a character class.
    # This function is used for literal context; avoid emitting raw NUL here.
    if len(b) == 1 and (b[0] < 0x20 or b[0] == 0x7F or b[0] >= 0x80):
        # Use a safe placeholder '.' for literal context; binary will be added via classes
        return b"."
    return b


def make_char_class(rng: random.Random) -> bytes:
    # Build a valid character class like [a-zA-Z0-9_], optionally negated
    parts = []
    # Maybe add ranges
    if rng.random() < 0.7:
        ranges = [
            (b"a", b"z"),
            (b"A", b"Z"),
            (b"0", b"9"),
        ]
        rng.shuffle(ranges)
        n = rng.randint(1, len(ranges))
        for lo, hi in ranges[:n]:
            parts.append(lo + b"-" + hi)
    # Add a few single atoms
    for _ in range(rng.randint(0, 3)):
        parts.append(_rand(rng, SAFE_CLASS_ATOMS))
    # Add safe binary via octal escapes or literal bytes inside class; since engine unknown,
    # we'll include raw bytes that generally work in classes
    for _ in range(rng.randint(0, 2)):
        parts.append(_rand(rng, BINARY_BYTES))
    body = b"".join(parts) or b"a"
    if rng.random() < 0.2:
        return b"[^" + body + b"]"
    return b"[" + body + b"]"


def maybe_quantify(rng: random.Random, atom: bytes) -> bytes:
    if rng.random() < 0.6:
        return atom + _rand(rng, QUANTIFIERS)
    return atom


def make_atom(rng: random.Random) -> bytes:
    choice = rng.random()
    if choice < 0.2:
        return _rand(rng, SPECIALS)
    elif choice < 0.5:
        # literal possibly escaped
        lit = _rand(rng, LITERALS + BINARY_BYTES)
        return escape_byte_for_pattern(lit)
    elif choice < 0.8:
        return make_char_class(rng)
    else:
        # small group
        inner = make_sequence(rng, max_atoms=rng.randint(1, 3))
        return b"(" + inner + b")"


def make_sequence(rng: random.Random, max_atoms: int) -> bytes:
    atoms = []
    for _ in range(max_atoms):
        atom = maybe_quantify(rng, make_atom(rng))
        atoms.append(atom)
    seq = b"".join(atoms)
    # Optionally add anchors at ends in a valid placement
    if rng.random() < 0.3 and (not seq.startswith(b"^")):
        seq = b"^" + seq
    if rng.random() < 0.3 and (not seq.endswith(b"$")):
        seq = seq + b"$"
    return seq


def make_alternation(rng: random.Random) -> bytes:
    # Build patterns like (seq1|seq2|seq3)
    branches = [make_sequence(rng, max_atoms=rng.randint(1, 4)) for _ in range(rng.randint(2, 4))]
    # Ensure no empty branches
    branches = [b or b"." for b in branches]
    return b"(" + b"|".join(branches) + b")"


def make_pattern(rng: random.Random) -> bytes:
    # Mix sequences and alternations
    parts = []
    n = rng.randint(1, 4)
    for _ in range(n):
        if rng.random() < 0.35:
            parts.append(make_alternation(rng))
        else:
            parts.append(make_sequence(rng, max_atoms=rng.randint(1, 6)))
    pat = b"".join(parts)
    # Keep pattern within reasonable compiled size; trim if needed
    return pat[:1024] if len(pat) > 1024 else pat


def random_word(rng: random.Random, length_range=(1, 16)) -> bytes:
    length = rng.randint(*length_range)
    alphabet = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_ -\t\n"
    return bytes(rng.choice(alphabet) for _ in range(length))


def make_text_haystack(rng: random.Random, pattern: bytes) -> bytes:
    # Create a text that likely matches the pattern.
    # Heuristics: extract simple hints from pattern and synthesize a string accordingly.
    out = bytearray()

    def add_range(lo: int, hi: int):
        out.append(rng.randint(lo, hi))

    i = 0
    while i < len(pattern) and len(out) < 1500:
        ch = pattern[i:i+1]
        nxt = pattern[i+1:i+2]
        # Anchors don't emit content
        if ch in (b"^", b"$"):
            i += 1
            continue
        # Dot => any char
        if ch == b".":
            reps = 1
            if nxt in (b"*", b"+", b"?"):
                if nxt == b"?":
                    reps = 0 if rng.random() < 0.5 else 1
                elif nxt == b"+":
                    reps = rng.randint(1, 5)
                else:
                    reps = rng.randint(0, 5)
                i += 2
            else:
                i += 1
            for _ in range(reps):
                add_range(32, 126)
            continue
        # Character class
        if ch == b"[":
            # Find closing bracket
            j = i + 1
            neg = False
            if j < len(pattern) and pattern[j:j+1] == b"^":
                neg = True
                j += 1
            # naive parse to next ']'
            while j < len(pattern) and pattern[j:j+1] != b"]":
                j += 1
            # Choose a likely member for positive, or a safe alnum for negated
            if not neg:
                # try to pick from simple ranges mentioned
                body = pattern[i+1+(1 if neg else 0):j]
                chosen = None
                if b"a-z" in body:
                    chosen = bytes([rng.randint(ord('a'), ord('z'))])
                elif b"A-Z" in body:
                    chosen = bytes([rng.randint(ord('A'), ord('Z'))])
                elif b"0-9" in body:
                    chosen = bytes([rng.randint(ord('0'), ord('9'))])
                else:
                    # fall back to alnum
                    chosen = random_word(rng, (1, 1))
                out += chosen
            else:
                # pick a non-alnum ASCII
                out += b"#"
            i = j + 1
            # handle quantifier after class
            if i < len(pattern) and pattern[i:i+1] in (b"*", b"+", b"?"):
                q = pattern[i:i+1]
                if q == b"?":
                    # already emitted one if needed, optional
                    pass
                elif q == b"+":
                    # emit a few more of the same category
                    for _ in range(rng.randint(0, 4)):
                        out += out[-1:]
                else:
                    # * -> optional extras
                    for _ in range(rng.randint(0, 3)):
                        out += out[-1:]
                i += 1
            continue
        # Group: consume but synthesize simple content
        if ch == b"(":
            # Seek matching ')' naively (no nesting handling complexity; fine for our generator)
            depth = 1
            j = i + 1
            while j < len(pattern) and depth > 0:
                if pattern[j:j+1] == b"(":
                    depth += 1
                elif pattern[j:j+1] == b")":
                    depth -= 1
                j += 1
            # Simple strategy: emit a word likely to match some group content
            out += random_word(rng, (1, 6))
            # handle quantifier
            if j < len(pattern) and pattern[j:j+1] in (b"*", b"+", b"?"):
                q = pattern[j:j+1]
                if q == b"+":
                    for _ in range(rng.randint(0, 3)):
                        out += out[-1:]
                elif q == b"*":
                    for _ in range(rng.randint(0, 2)):
                        out += out[-1:]
                # '?' do nothing extra
                j += 1
            i = j
            continue
        # Escape sequence or literal
        # Treat any backslash as escaping next char literally
        if ch == b"\\" and i + 1 < len(pattern):
            out += pattern[i+1:i+2]
            i += 2
            continue
        # Quantifiers after literal handled by next iteration; emit literal
        out += (ch if 32 <= ch[0] <= 126 else b"a")
        # If next is quantifier, add repeats
        if nxt in (b"*", b"+", b"?"):
            if nxt == b"+":
                out += ch * rng.randint(0, 4)
            elif nxt == b"*":
                out += ch * rng.randint(0, 3)
            # '?' optional: no action
            i += 2
        else:
            i += 1

    # Optionally add prefix/suffix noise when not anchored
    if not pattern.startswith(b"^") and rng.random() < 0.7:
        out = bytearray(random_word(rng, (0, 8)) + out)
    if not pattern.endswith(b"$") and rng.random() < 0.7:
        out = bytearray(out + random_word(rng, (0, 8)))

    return bytes(out[:2048])


def pack_for_fuzzer(pattern: bytes, text: bytes) -> bytes:
    # Concatenate two len-prefixed blobs to satisfy multiple FUZZ_PARAM_STR consumers.
    # The fuzzer will pull from the same input; using length-prefixing lets it split.
    # Format: [u32 len_p][pattern][u32 len_t][text]
    # The harness may not parse lengths, but typical fuzzers feed each FUZZ_PARAM_STR
    # sequentially; this layout increases chance both substrings are non-empty and valid.
    lp = struct.pack("<I", len(pattern))
    lt = struct.pack("<I", len(text))
    blob = lp + pattern + lt + text
    return blob[:MAX_OUTPUT]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create several candidate patterns and pick one to diversify outputs
    candidates = [make_pattern(rng) for _ in range(3)]
    pattern = _rand(rng, candidates)
    # Ensure non-empty pattern to avoid trivial failures
    if not pattern:
        pattern = b"."
    text = make_text_haystack(rng, pattern)
    # Ensure non-empty text; max_match_length is chosen in stub from another param,
    # but having some content is beneficial
    if not text:
        text = b"sample"
    return pack_for_fuzzer(pattern, text)
